package com.yigongbao.backup.admin;
import cn.dev33.satoken.stp.StpUtil; import com.yigongbao.backup.common.ApiResponse; import com.yigongbao.backup.config.ConfigService; import com.yigongbao.backup.config.PersistentConfigService; import com.yigongbao.backup.config.ConfigurationChangeGuard; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.UUID;
/** 管理员版本化配置查询和 CAS 更新接口。 */
@RestController @RequestMapping("/api/v1/admin/configs") @RequiredArgsConstructor
public class AdminConfigController {private final PersistentConfigService configs; private final ConfigurationChangeGuard guard; private static String rid(){return UUID.randomUUID().toString();} @GetMapping("/categories") public ApiResponse<java.util.List<PersistentConfigService.Category>> categories(){StpUtil.checkRole("ADMIN");return ApiResponse.ok(configs.categories(),rid());} @GetMapping public ApiResponse<java.util.List<ConfigService.Entry>> list(){StpUtil.checkRole("ADMIN");return ApiResponse.ok(configs.list(),rid());} @GetMapping("/{key}") public ApiResponse<ConfigService.Entry> get(@PathVariable("key") String key){StpUtil.checkRole("ADMIN");return ApiResponse.ok(configs.get(key),rid());} @PutMapping("/{key}") public ApiResponse<ConfigService.Entry> put(@PathVariable("key") String key,@RequestBody Command c){StpUtil.checkRole("ADMIN");guard.validate(key,c.value());return ApiResponse.ok(configs.put(key,c.value(),c.expectedVersion(),StpUtil.getLoginIdAsLong()),rid());} public record Command(String value,int expectedVersion){} }
